ived","type":"CHECKBOX","label":"Tillatelsen er signert og arkivert"},{"id":"hw_notes","type":"TEXTAREA","label":"Merknader / avvik","required":false},{"id":"hw_sig_1","type":"TEXT","label":"Signatur – utførende","required":false},{"id":"hw_sig_2","type":"TEXT","label":"Signatur – brannvakt","required":false},{"id":"hw_sig_3","type":"TEXT","label":"Signatur – arbeidsleder","required":false},{"id":"hw_sig_4","type":"TEXT","label":"Signatur – utsteder / godkjenner","required":false}]') ON CONFLICT ("id") DO NOTHING;
